<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import {avatarSourceValid,type AvatarGateway} from '../application/avatars';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureText} from '$lib/shared/presentation/messages';
 let {gateway,kind,ownerId,name,actorId,onsaved}:{gateway:AvatarGateway;kind:'user'|'team';ownerId:string;name:string;actorId:string;onsaved?:()=>void}=$props();
 const {locale}=useLocale();let busy=$state(false),message=$state(''),failed=$state(false),version=$state(0);
 let pending=$state<File|null>(null),preview=$state('');
 function cancel(){if(preview)URL.revokeObjectURL(preview);preview='';pending=null;}
 onDestroy(cancel);
 $effect(()=>{actorId;ownerId;untrack(cancel);});
 const initials=$derived([...name.trim()].slice(0,2).join('').toUpperCase()||'Q');
 function upload(event:Event){const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file||busy)return;cancel();message='';if(!avatarSourceValid(file)){message=text($locale,'JPEG/PNG/WebP, 5 МБ дейін.','JPEG/PNG/WebP, до 5 МБ.');return;}pending=file;preview=URL.createObjectURL(file);}
 async function confirm(){if(!pending||busy)return;const file=pending,actor=actorId,owner=ownerId;busy=true;try{await gateway.upload(kind,owner,file,actor);if(actor!==actorId||owner!==ownerId)return;failed=false;version=Date.now();message=text($locale,'Аватар сақталды.','Аватар сохранён.');cancel();onsaved?.();}catch(error){if(actor===actorId&&owner===ownerId)message=failureText($locale,error);}finally{busy=false;}}

</script>
<div class="avatar-editor"><span class="avatar" aria-hidden="true">{#if !failed}<img src={'/media/avatars/'+kind+'/'+encodeURIComponent(ownerId)+'?v='+version} alt="" onerror={()=>failed=true}/>{:else}{initials}{/if}</span><div class="avatar-controls"><label class="avatar-file"><input type="file" aria-label={text($locale,'Аватарды өзгерту','Изменить аватар')} accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={upload}/><span>{text($locale,'Суретті таңдау','Выбрать изображение')}</span></label><span class="muted">{text($locale,'JPEG/PNG/WebP, 5 МБ дейін. Ортадан шаршы қиылады.','JPEG/PNG/WebP, до 5 МБ. Обрезается квадратом по центру.')}</span></div></div>
{#if pending}<section class="crop-preview" aria-label={text($locale,'Аватарды алдын ала қарау','Предпросмотр аватара')}><p>{text($locale,'Сақталатын орталық шаршы және дөңгелек көрініс.','Центральная квадратная обрезка и круглый вид после сохранения.')}</p><div><img src={preview} alt={text($locale,'Шаршы қиынды','Квадратная обрезка')}/><img class="round" src={preview} alt={text($locale,'Дөңгелек көрініс','Круглый вид')}/></div><button class="button primary" disabled={busy} onclick={confirm}>{text($locale,'Сақтау','Сохранить')}</button><button class="button" disabled={busy} onclick={cancel}>{text($locale,'Бас тарту','Отмена')}</button></section>{/if}
{#if message}<p role="status">{message}</p>{/if}
<style>.crop-preview{padding:12px;border:1px solid var(--line)}.crop-preview>div{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.crop-preview img{width:112px;height:112px;object-fit:cover;object-position:center}.crop-preview .round{border-radius:50%}.crop-preview button{margin:4px}.avatar-editor{display:flex;align-items:center;gap:16px;margin:20px 0;min-width:0}.avatar{display:grid;place-items:center;flex-shrink:0;width:64px;height:64px;border-radius:50%;background:var(--panel);border:1px solid var(--line);font-weight:650}.avatar img{width:64px;height:64px;object-fit:cover;border-radius:50%}.avatar-controls{display:grid;gap:8px;min-width:0}.avatar-file{position:relative;display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:8px 14px;border:1px solid var(--line);border-radius:8px;cursor:pointer;font-size:13px;justify-self:start;max-width:100%}.avatar-file:focus-within{outline:2px solid var(--accent);outline-offset:3px}.avatar-file:has(input:disabled){opacity:.6;cursor:wait}.avatar-file input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:inherit}.avatar-file span{pointer-events:none}input{max-width:100%;min-height:44px}.muted{font-size:12px;color:var(--muted)}</style>
